import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    out_lines = []

    for _ in range(t):
        try:
            n = int(next(iterator))
            k = int(next(iterator))
        except StopIteration:
            break

        used = [False] * n
        pairs = []

        if k < n // 2:
            if k % 2 == 1:
                pairs.append((k ^ (n - 1), k))
                used[k] = True
                used[k ^ (n - 1)] = True
                current_k = k
            else:
                pairs.append((k, k ^ (n - 1)))
                used[k] = True
                used[k ^ (n -1)] = True
                current_k = k

            target = n // 2
            while current_k < target:
                x = current_k
                y = current_k ^ (n - 1)
                if not used[x] and not used[y]:
                    pairs.append((x, y))
                    used[x] = True
                    used[y] = True
                    current_k += 1
                else:
                    break

            if current_k != target:
                out_lines.append("-1")
                continue

            remaining = [i for i in range(n) if not used[i]]
            for i in range(0, len(remaining), 2):
                pairs.append((remaining[i], remaining[i+1]))

        else:
            pairs.append((k, k ^ (n - 1)))
            used[k] = True
            used[k ^ (n - 1)] = True

            remaining = [i for i in range(n) if not used[i] and i != n - 1]
            pairs.append((n - 1, remaining[0]))
            used[n - 1] = True
            used[remaining[0]] = True

            remaining = [i for i in range(n) if i not in {k, k ^ (n - 1), n - 1, remaining[0]}]

            for i in range(0, len(remaining), 2): 
                pairs.append((remaining[i], remaining[i+1]))

        total_and = 0
        for a, b in pairs:
            total_and += (a & b)

        if total_and != k:
            out_lines.append("-1")
        else:
            for a, b in pairs:
                out_lines.append(f"{a} {b}")

    sys.stdout.write('\n'.join(out_lines) + '\n')

if __name__ == "__main__":
    solve()
